```python
import json
from pathlib import Path

RENAME_MAP: dict[str, str] = {
    "Gaming": "01_FPS_Gaming",
    "Minecraft": "02_Minecraft",
}
REMOVED_SCENES: set[str] = {"Just Chatting"}

def audit_script_references(scripts_dir: Path) -> dict[str, list[str]]:
    """Find stale scene names in Python/Lua scripts using strict UTF-8."""
    stale: dict[str, list[str]] = {}
    targets = set(RENAME_MAP) | REMOVED_SCENES
    for ext in ("*.py", "*.lua"):
        for path in sorted(scripts_dir.rglob(ext)):
            text = path.read_text(encoding="utf-8", errors="strict")
            hits = [name for name in targets if name in text]
            if hits:
                stale[path.name] = hits
    return stale
```

